import { useState, type FormEvent } from 'react';
import { JxInputField, JxButton, JxToastViewport, useJxToastQueue } from '@jinx-ui/react';

export default function SubscribeForm() {
  const toasts = useJxToastQueue();
  const [email, setEmail] = useState('');

  const submit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    toasts.push({
      title: 'Готово',
      message: `Письмо отправлено на ${email}`,
      variant: 'success',
    });
    setEmail('');
  };

  return (
    <div style={{ maxWidth: 360 }}>
      <form
        onSubmit={submit}
        style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-r-sm)' }}
      >
        <JxInputField
          label="Почта"
          type="email"
          required
          value={email}
          onChange={(event) => setEmail(event.target.value)}
        />
        <JxButton type="submit">Подписаться</JxButton>
      </form>
      <JxToastViewport items={toasts.items} onDismiss={toasts.dismiss} position="top-right" />
    </div>
  );
}

